:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c63ff;
  --primary-hover: #5a52d5;
  --accent: #ff6584;
  --text: #f0f0f5;
  --text-muted: #a0a0b0;
  --card-back: #3a3a55;
  --card-back-hover: #4a4a6a;
  --matched: #4caf50;
  --focus-ring: #ffd166;
  --radius: 12px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 560px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--primary);
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.stats {
  font-size: 1.125rem;
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.moves-label {
  color: var(--text-muted);
}

.moves-count {
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1 / 1;
}

.card {
  background: var(--card-back);
  border: 2px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  position: relative;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
  outline: none;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.card:hover:not(.matched):not(.flipped) {
  background: var(--card-back-hover);
}

.card:focus-visible {
  border-color: var(--focus-ring);
  box-shadow: 0 0 0 3px rgba(255, 209, 102, 0.4);
}

.card:active:not(.matched):not(.flipped) {
  transform: scale(0.96);
}

.card.flipped {
  background: var(--primary);
  cursor: default;
}

.card.matched {
  background: var(--matched);
  cursor: default;
  opacity: 0.8;
}

.card.matched::after {
  content: '✓';
  font-size: 1.25rem;
  color: #fff;
  font-weight: 700;
}

.card.flipped .card-face {
  display: block;
}

.card-face {
  display: none;
  width: 100%;
  height: 100%;
  border-radius: calc(var(--radius) - 2px);
}

.win-message {
  background: var(--matched);
  color: #fff;
  padding: 12px 20px;
  border-radius: var(--radius);
  font-size: 1.125rem;
  font-weight: 600;
  text-align: center;
  animation: pop 0.3s ease;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.new-game-btn {
  background: var(--primary);
  color: #fff;
  border: none;
  padding: 12px 32px;
  font-size: 1.125rem;
  font-weight: 600;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  outline: none;
  font-family: inherit;
}

.new-game-btn:hover {
  background: var(--primary-hover);
}

.new-game-btn:focus-visible {
  box-shadow: 0 0 0 3px var(--focus-ring);
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .board {
    gap: 8px;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
    '#9b5de5', '#f15bb5', '#00bbf9', '#fee440'
  ];

  const boardEl = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const winMessageEl = document.getElementById('win-message');
  const finalMovesEl = document.getElementById('final-moves');
  const newGameBtn = document.getElementById('new-game');

  let deck = [];
  let flipped = [];
  let matchedCount = 0;
  let moves = 0;
  let lockBoard = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createDeck() {
    const pairs = COLORS.flatMap(function (color) {
      return [{ color: color, id: color }, { color: color, id: color }];
    });
    return shuffle(pairs);
  }

  function renderBoard() {
    boardEl.innerHTML = '';
    deck.forEach(function (cardData, index) {
      const card = document.createElement('button');
      card.type = 'button';
      card.className = 'card';
      card.dataset.index = index;
      card.dataset.color = cardData.color;
      card.setAttribute('aria-label', 'Hidden card ' + (index + 1));
      card.setAttribute('aria-pressed', 'false');

      const face = document.createElement('div');
      face.className = 'card-face';
      face.style.background = cardData.color;
      card.appendChild(face);

      card.addEventListener('click', handleCardClick);
      boardEl.appendChild(card);
    });
  }

  function handleCardClick(e) {
    const card = e.currentTarget;
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.setAttribute('aria-pressed', 'true');
    card.setAttribute('aria-label', 'Revealed card');
    flipped.push(card);

    if (flipped.length === 2) {
      moves++;
      movesEl.textContent = moves;
      lockBoard = true;
      checkMatch();
    }
  }

  function checkMatch() {
    const a = flipped[0];
    const b = flipped[1];
    const isMatch = a.dataset.color === b.dataset.color;

    if (isMatch) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.disabled = true;
      b.disabled = true;
      matchedCount++;
      flipped = [];
      lockBoard = false;
      if (matchedCount === COLORS.length) {
        showWin();
      }
    } else {
      setTimeout(function () {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.setAttribute('aria-pressed', 'false');
        b.setAttribute('aria-pressed', 'false');
        a.setAttribute('aria-label', 'Hidden card');
        b.setAttribute('aria-label', 'Hidden card');
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function showWin() {
    finalMovesEl.textContent = moves;
    winMessageEl.hidden = false;
  }

  function newGame() {
    deck = createDeck();
    flipped = [];
    matchedCount = 0;
    moves = 0;
    lockBoard = false;
    movesEl.textContent = '0';
    winMessageEl.hidden = true;
    renderBoard();
  }

  newGameBtn.addEventListener('click', newGame);
  newGame();
})();
